// 时间轴数据：中央脊椎 + 上下分支
// ============================================================

export interface TimelineNode {
  id: string;
  year: string;          // 绝对年份（显示在中央轴线上）
  century: string;       // 世纪标签
  centuryZh: string;
  centuryEn: string;
  // 表层标签（上方：西洋建筑史）
  westernLabel: string;
  westernLabelZh: string;
  westernLabelEn: string;
  westernTags: string[];
  westernTagsZh: string[];
  westernTagsEn: string[];
  // 表层标签（下方：日本建筑史）
  eastAsianLabel: string;
  eastAsianLabelZh: string;
  eastAsianLabelEn: string;
  eastAsianTags: string[];
  eastAsianTagsZh: string[];
  eastAsianTagsEn: string[];
  // 地域标签（用于比较表格表头，替代硬编码的"西方"/"东亚"）
  westernRegionLabel: string;
  westernRegionLabelZh: string;
  westernRegionLabelEn: string;
  easternRegionLabel: string;
  easternRegionLabelZh: string;
  easternRegionLabelEn: string;
  // 里层数据
  macroTendency: string;
  macroTendencyZh: string;
  macroTendencyEn: string;
  westernDetail: string;
  westernDetailZh: string;
  westernDetailEn: string;
  eastAsianDetail: string;
  eastAsianDetailZh: string;
  eastAsianDetailEn: string;
  // 深度对比表格
  comparison: {
    dimension: string;
    dimensionZh: string;
    dimensionEn: string;
    western: string;
    westernZh: string;
    westernEn: string;
    eastAsian: string;
    eastAsianZh: string;
    eastAsianEn: string;
  }[];
  // 底部补充
  footnote: string;
  footnoteZh: string;
  footnoteEn: string;
  // 关联学习卡片
  relatedCardIds?: string[];
  // 补充定位（可选：仅用于说明传播关系或防止误解）
  supplementaryNote?: string;
  supplementaryNoteZh?: string;
  supplementaryNoteEn?: string;
  // 考试关键词（该时代最应记忆的建筑/技术/样式，3–5项）
  examKeywords: string[];
  examKeywordsZh: string[];
  examKeywordsEn: string[];
  /** Region-tagged content for the comparison modules.  Do not infer regions from display text. */
  trends?: TimelineRegionalText[];
  examKeywordEntries?: TimelineKeyword[];
  /** Stable building ids from the normalized architecture database. */
  buildingIds?: string[];
}

export type TimelineRegion = "western" | "japan";

export interface TimelineRegionalText {
  region: TimelineRegion;
  ja: string;
  zh: string;
  en?: string;
}

export interface TimelineKeyword extends TimelineRegionalText {
  type: "building" | "style" | "structure" | "spatial-form" | "religion" | "ideology";
}

