    westernLabel: "ビザンツ建築の興隆",
    westernLabelZh: "拜占庭建筑的兴隆",
    westernLabelEn: "Rise of Byzantine architecture",
    westernTags: ["ハギア・ソフィア", "ペンデンティブ", "モザイク"],
